class Link(TextElement):
    @classmethod
    def create(cls, markdown: "Markdown", token: Token) -> "MarkdownElement":
        url = token.attrs.get("href", "#")
        return cls(token.content, str(url))

    def __init__(self, text: str, href: str):
        self.text = Text(text)
        self.href = href


